script:
test("before 14:00 on a business day ships that day and one transit day delivers the next business day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});

test("cutoff exactly 14:00 is not before 14:00 so it ships the next business day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});

test("cutoff one minute below 14:00 still ships that business day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T13:59", transitDays: 2, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-03" });
});

test("cutoff one minute above 14:00 ships the next business day and delivery skips the weekend", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:01", transitDays: 2, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-06" });
});

test("Friday after 14:00 skips Saturday Sunday and the Monday holiday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});

test("empty holiday list means the same Friday booking ships Monday not Tuesday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-08" });
});

test("booking on a holiday ships the next business day when that holiday is first in the list", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 2, holidays: ["2026-07-06", "2026-01-01", "2026-12-25"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});

test("booking on a holiday ships the next business day when that holiday is in the middle of the list", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 2, holidays: ["2026-01-01", "2026-07-06", "2026-12-25"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});

test("booking on a holiday ships the next business day when that holiday is last in the list", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 2, holidays: ["2026-01-01", "2026-12-25", "2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});

test("Sunday is not a ship day and transitDays 0 makes deliveryDate equal shipDate", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-05T08:00", transitDays: 0, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-06" });
});

test("leap day is a business ship day and a holiday on the 1st is not counted in transit", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2024-02-28T15:00", transitDays: 2, holidays: ["2024-03-01"] }), { shipDate: "2024-02-29", deliveryDate: "2024-03-05" });
});

test("31 December after cutoff ships 1 January and transitDays 2 and 2.0 are the same", function () {
  var expected = { shipDate: "2027-01-01", deliveryDate: "2027-01-05" };
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-12-31T15:00", transitDays: 2, holidays: [] }), expected);
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-12-31T15:00", transitDays: 2.0, holidays: [] }), expected);
});

test("Saturday before 14:00 ships the next business day and 5 transit days cross the following weekend", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-04T09:00", transitDays: 5, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-13" });
});

test("transitDays one step below the minimum 0 is rejected", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T11:00", transitDays: -1, holidays: [] });
  }, /^invalid transitDays$/);
});

test("transitDays that is not a whole number including 2.5 is rejected", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T11:30", transitDays: 2.5, holidays: [] });
  }, /^invalid transitDays$/);
});

test("an input field other than bookedAt transitDays or holidays is rejected", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [], customerId: "C9" });
  }, /^unknown field: customerId$/);
});
